SELECT id,source_id,source_url,title,content_hash,is_active,inactive_reason,ph_eligibility,geo_scope,posted_at,scraped_at,updated_at,CASE WHEN source_url IN ('https://apply.workable.com/j/8902E9B839','https://apply.workable.com/j/13FFDFE94E','https://apply.workable.com/j/BB4A8BD9FA') THEN 'EXACT_URL' ELSE 'HASH_ONLY' END AS match_basis FROM opportunities WHERE source_url IN ('https://apply.workable.com/j/8902E9B839','https://apply.workable.com/j/13FFDFE94E','https://apply.workable.com/j/BB4A8BD9FA') OR content_hash IN ('4a139740470ccf2f','9842df5277a49f53','c3bd749ac0336b0b') ORDER BY id LIMIT 7;
